private int EstimateSubjectLineCount(DataRow drw)
{
    string strName = "";
    if (drw != null && drw.Table.Columns.Contains("SubjectName") && drw["SubjectName"] != DBNull.Value)
        strName = Convert.ToString(drw["SubjectName"]).Trim();
    if (strName.Length < 1)
        return 1;

    const int intCharsPerLine = 30;
    string[] arrWords = strName.Split(new char[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
    if (arrWords.Length < 1)
        return 1;

    int intLines = 1;
    int intCurrent = 0;
    int i;
    for (i = 0; i < arrWords.Length; i++)
    {
        int intWord = arrWords[i].Length;
        if (intCurrent < 1)
            intCurrent = intWord;
        else if (intCurrent + 1 + intWord > intCharsPerLine)
        {
            intLines++;
            intCurrent = intWord;
        }
        else
            intCurrent = intCurrent + 1 + intWord;
    }
    if (intLines < 1)
        intLines = 1;
    return intLines;
}

private int EstimateColumnLineCount(DataTable dtbMarks, int intFrom, int intTo)
{
    int intTotal = 0;
    int i;
    for (i = intFrom; i < intTo; i++)
        intTotal += EstimateSubjectLineCount(dtbMarks.Rows[i]);
    return intTotal;
}

private int GetBalancedLeftCount(DataTable dtbMarks)
{
    int intCount = dtbMarks.Rows.Count;
    if (intCount <= 1)
        return intCount;

    int intFrom = intCount / 2;
    if (intFrom < 1)
        intFrom = 1;
    int intTo = intCount - 1;
    if (intTo < intFrom)
        intTo = intFrom;

    int intBest = intCount / 2 + 1;
    if (intBest > intCount)
        intBest = intCount;
    if (intBest < 1)
        intBest = 1;

    int intBestDiff = int.MaxValue;
    int intLeft;
    for (intLeft = intFrom; intLeft <= intTo; intLeft++)
    {
        int intLeftH = EstimateColumnLineCount(dtbMarks, 0, intLeft);
        int intRightH = EstimateColumnLineCount(dtbMarks, intLeft, intCount);
        int intDiff = intLeftH - intRightH;
        if (intDiff < 0)
            intDiff = -intDiff;

        if (intDiff < intBestDiff || (intDiff == intBestDiff && intLeftH >= intRightH))
        {
            intBestDiff = intDiff;
            intBest = intLeft;
        }
    }
    return intBest;
}

