private string BuildBangDiemMarkTablesHtml(DataTable dtbMarks)
{
    int intCount = dtbMarks.Rows.Count;
    int intLeftCount = GetBalancedLeftCount(dtbMarks);

    int intLeftH = EstimateColumnLineCount(dtbMarks, 0, intLeftCount);
