        intPadLeft = intRightH - intLeftH;

    string strHeader = BuildBangDiemMarkTableHeaderHtml();
    StringBuilder sb = new StringBuilder();
    sb.Append("<div class='tables-wrap'><table><tr><td>");

    sb.Append("<table class='mark-table'>").Append(strHeader).Append("<tbody>");
    int i;
    for (i = 0; i < intLeftCount; i++)
        sb.Append(BuildBangDiemMarkRowHtml(dtbMarks.Rows[i], i + 1));
    for (i = 0; i < intPadLeft; i++)
        sb.Append(BuildBangDiemEmptyRowHtml());
    sb.Append("</tbody></table>");

    sb.Append("</td><td>");
    sb.Append("<table class='mark-table'>").Append(strHeader).Append("<tbody>");
    for (i = intLeftCount; i < intCount; i++)
        sb.Append(BuildBangDiemMarkRowHtml(dtbMarks.Rows[i], i + 1));
    for (i = 0; i < intPadRight; i++)
